function tryParseJson(str) {
  try {
    return JSON.parse(str);
  } catch {
    return null;
  }
}

/**
 * Parses XML-style tool calls (e.g. <tool_call>write_file<param_key>...</param_value></tool_call>
 * or <tool_call>write_file<arg_key>content</arg_key><arg_value>...</arg_value></tool_call>)
 * Generated by models fine-tuned on Hermes/Qwen function calling formats.
 */
function extractXmlToolCalls(rawText) {
  if (!rawText) return null;
  if (
    !rawText.includes("<tool_call>") &&
    !rawText.includes("<function_call>") &&
    !rawText.includes("<call>")
  ) {
    return null;
  }

  const actions = [];
  const toolCallRegex =
    /<(?:tool_call|function_call|call)>([\s\S]*?)<\/(?:tool_call|function_call|call)>/gi;
  let match;

  while ((match = toolCallRegex.exec(rawText)) !== null) {
    const block = match[1].trim();

    // Check if block contains JSON directly: <tool_call>{"name": "...", "arguments": {...}}</tool_call>
    try {
      const parsedJson = JSON.parse(block);
      if (parsedJson) {
        const name = parsedJson.name || parsedJson.action || "create_file";
        const args =
          parsedJson.arguments || parsedJson.parameters || parsedJson;
        let action = "create_file";
        if (name.includes("delete") || name.includes("remove"))
          action = "delete_file";
        else if (name.includes("run") || name.includes("exec"))
          action = "run_code";
        else if (name.includes("write") || name.includes("edit"))
          action = "write_file";

        actions.push({
          action,
          path: args.path || args.filename || args.file || "",
          content: args.content || args.code || "",
          command: args.command || args.cmd || "",
        });
        continue;
      }
    } catch {}

    const nameMatch = block.match(/^([a-zA-Z0-9_-]+)/);
    const actionName = (nameMatch ? nameMatch[1] : "write_file").toLowerCase();

    const params = {};
    const paramRegex =
      /<(?:arg|param|parameter)_(?:key|name)>([\s\S]*?)<\/(?:arg|param|parameter)_(?:key|name)>\s*<(?:arg|param|parameter)_(?:val|value)>([\s\S]*?)<\/(?:arg|param|parameter)_(?:val|value)>/gi;
    let pMatch;
    while ((pMatch = paramRegex.exec(block)) !== null) {
      params[pMatch[1].trim()] = pMatch[2].trim();
    }

    let action = "create_file";
    if (actionName.includes("delete") || actionName.includes("remove"))
      action = "delete_file";
    else if (actionName.includes("run") || actionName.includes("exec"))
      action = "run_code";
    else if (actionName === "write_file" || actionName === "edit_file")
      action = "write_file";

    const path = params.path || params.file || params.filename || "";
    const content = params.content || params.code || "";
    const command = params.command || params.cmd || "";

    if (action === "delete_file" && path) {
      actions.push({ action: "delete_file", path });
    } else if (path || content) {
      actions.push({
        action,
        path: path || "solution.py",
        content,
      });
    } else if (command) {
      actions.push({ action: "run_code", command });
    }
  }

  // Extract conversational message outside tool tags
  const textWithoutTools = rawText
    .replace(
      /<(?:tool_call|function_call|call)>[\s\S]*?<\/(?:tool_call|function_call|call)>/gi,
      ""
    )
    .trim();

  if (textWithoutTools) {
    actions.push({
      action: "chat",
      message: textWithoutTools,
    });
  } else if (actions.length > 0) {
    const fileAction = actions.find(
      (a) => a.action === "create_file" || a.action === "write_file"
    );
    if (fileAction && fileAction.path) {
      actions.push({
        action: "chat",
        message: `Created and implemented \`${fileAction.path}\` based on your request.`,
      });
    }
  }

  return actions.length > 0 ? { actions } : null;
}

/**
 * Character-by-character balanced JSON actions extractor.
 */
function parseBalancedActions(str) {
  if (!str) return null;

  const actionsIdx = str.indexOf('"actions"');
  if (actionsIdx === -1) return null;

  const bracketIdx = str.indexOf("[", actionsIdx);
  if (bracketIdx === -1) return null;

  const actions = [];
  let inString = false;
  let escape = false;
  let depth = 0;
  let objStart = -1;

  for (let i = bracketIdx + 1; i < str.length; i++) {
    const ch = str[i];
    if (escape) {
      escape = false;
      continue;
    }
    if (ch === "\\") {
      escape = true;
      continue;
    }
    if (ch === '"') {
      inString = !inString;
      continue;
    }
    if (inString) continue;

    if (ch === "{") {
      if (depth === 0) objStart = i;
      depth++;
    } else if (ch === "}") {
      depth--;
      if (depth === 0 && objStart !== -1) {
        let objStr = str.slice(objStart, i + 1);
        let parsed = tryParseJson(objStr);
        if (!parsed) {
          objStr = objStr.replace(/"\s*\}{2,}\s*$/g, '"}');
          objStr = objStr.replace(/,\s*}/g, "}");
          parsed = tryParseJson(objStr);
        }
        if (parsed && parsed.action) {
          actions.push(parsed);
        }
        objStart = -1;
      } else if (depth < 0) {
        depth = 0;
      }
    } else if (ch === "]" && depth === 0) {
      break;
    }
  }

  return actions.length > 0 ? { actions } : null;
}

function sanitizeJsonString(str) {
  if (!str) return "";
  let clean = str.trim();

  if (clean.includes("```")) {
    const fenceMatch = clean.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (fenceMatch && fenceMatch[1]) {
      clean = fenceMatch[1].trim();
    }
  }

  const firstBrace = clean.indexOf("{");
  const lastBrace = clean.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    clean = clean.slice(firstBrace, lastBrace + 1);
  }

  clean = clean.replace(new RegExp('\"\\s*\\}\\}+\\s*(?=[\\s\\}\\]]|$)', 'g'), '"}');
  clean = clean.replace(new RegExp(',\\s*([\\]\\}])', 'g'), "$1");

  return clean;
}

function extractMarkdownCodeFallback(rawText) {
  const codeBlockMatch = rawText.match(/```([a-zA-Z0-9_-]+)?\s*([\s\S]+?)\s*```/);
  if (!codeBlockMatch) return null;

  const lang = (codeBlockMatch[1] || "").toLowerCase();
  const code = codeBlockMatch[2].trim();

  let filename = "solution.py";
  if (lang === "java" || code.includes("class ") || code.includes("public static void main")) {
    const classMatch = code.match(/public\s+class\s+([A-Za-z0-9_]+)/);
    filename = classMatch ? `${classMatch[1]}.java` : "Solution.java";
  } else if (lang === "py" || lang === "python" || code.includes("def ") || code.includes("import ")) {
    filename = "solution.py";
  } else if (lang === "cpp" || lang === "c++" || code.includes("#include <iostream>")) {
    filename = "solution.cpp";
  } else if (lang === "c" || code.includes("#include <stdio.h>")) {
    filename = "solution.c";
  } else if (lang === "js" || lang === "javascript") {
    filename = "index.js";
  } else if (lang === "html") {
    filename = "index.html";
  }

  const explanation = rawText.replace(/```[a-zA-Z0-9_-]*\s*[\s\S]+?\s*```/, "").trim();

  return {
    actions: [
      {
        action: "create_file",
        path: filename,
        content: code,
      },
      {
        action: "chat",
        message: explanation || `Created ${filename} with the requested code.`,
      },
    ],
  };
}

export function parseAI(response) {
  if (!response) {
    return {
      actions: [
        {
          action: "chat",
          message: "No response from AI.",
        },
      ],
    };
  }

  const text = typeof response === "string" ? response.trim() : JSON.stringify(response);

  // 1. Check for XML-style tool calls (Hermes/Qwen function calling tags)
  const xmlTools = extractXmlToolCalls(text);
  if (xmlTools) {
    return xmlTools;
  }

  // 2. Direct JSON parse
  const direct = tryParseJson(text);
  if (direct) {
    if (direct.actions && Array.isArray(direct.actions)) return direct;
    if (Array.isArray(direct)) return { actions: direct };
    if (direct.action) return { actions: [direct] };
    if (direct.message) return { actions: [{ action: "chat", message: direct.message }] };
  }

  // 3. Character-by-character balanced actions parser
  const balanced = parseBalancedActions(text);
  if (balanced && balanced.actions?.length > 0) {
    return balanced;
  }

  // 4. Sanitized JSON parse
  const sanitized = sanitizeJsonString(text);
  const sanitizedParsed = tryParseJson(sanitized);
  if (sanitizedParsed) {
    if (sanitizedParsed.actions && Array.isArray(sanitizedParsed.actions)) return sanitizedParsed;
    if (Array.isArray(sanitizedParsed)) return { actions: sanitizedParsed };
    if (sanitizedParsed.action) return { actions: [sanitizedParsed] };
  }

  // 5. Markdown code block fallback
  const markdownFallback = extractMarkdownCodeFallback(text);
  if (markdownFallback) {
    return markdownFallback;
  }

  // 6. Final fallback
  return {
    actions: [
      {
        action: "chat",
        message: text,
      },
    ],
  };
}
